// One read of the clock for every derived default below, so ages and birth years
// cannot disagree with each other.
const DEFAULT_TODAY_YEAR = new Date().getFullYear();

const DEFAULT_PERSONAL_INFO = {
  myAge: 35,
  spouseAge: 33,
  myRetirementAge: 65,
  spouseRetirementAge: 65,
  // Derived, never hardcoded. These were literal 1991/1993, which agreed with
  // myAge/spouseAge only during the year they were written — every year after,
  // the starter plan claimed to be 35 while the RMD and FRA math ran off a
  // birth year that made them older.
  myBirthYear: DEFAULT_TODAY_YEAR - 35,
  spouseBirthYear: DEFAULT_TODAY_YEAR - 33,
  filingStatus: 'married_joint',
  state: 'Alabama',
  // 61% of the $180,000 household gross below. The familiar "70-80% of
  // pre-retirement income" rule is quoted on GROSS pay, which for this couple
  // still contains 7.65% FICA and an 11%-of-pay savings rate — both of which
  // stop at retirement. Netting those out, 61% of gross is roughly 75% of what
  // they actually live on today, which is the middle of the conventional range.
  // It is also what this savings rate genuinely supports over a 33-year
  // retirement: the plan clears it with ~16% of spending headroom, where 70% of
  // gross would leave under 2%. A starter scenario should be comfortable, not
  // balanced on a knife edge — but it must not be a fantasy either.
  desiredRetirementIncome: 110000,
  inflationRate: 0.03,
  withdrawalPriority: ['pretax', 'brokerage', 'roth'], // Order: first to last
  charitableGivingPercent: 0, // Percentage of retirement spending donated to charity (enables QCD strategy)
  // Planned Roth conversions: move this much per year from largest pre-tax account to largest Roth account.
  // Conversions are treated as ordinary income in the projection engine (affects taxes and SS taxation).
  rothConversionAmount: 0,       // Annual conversion amount (0 = disabled)
  rothConversionInflationAdjust: true, // true: amount is today's $, indexed each year; false: same nominal amount every year
  rothConversionStartAge: 0,     // Age to begin converting (0 = use smart default: myRetirementAge)
  rothConversionEndAge: 0,       // Age to stop converting (0 = use smart default: rmdStartAge - 1)
  rothConversionBracket: '',     // If set ('22%','24%','32%'), fill to this bracket instead of fixed amount
  rothConversionIrmaaTier: null, // If an integer, fill to that IRMAA tier's MAGI edge instead. Mutually
                                 // exclusive with the two above; null means "not this mode". Listed here
                                 // so the third mode is discoverable next to the other two rather than
                                 // existing only where it happens to be read.
  rothConversionTaxSource: 'withdrawal', // 'withdrawal' = tax paid via normal withdrawal priority, 'brokerage' = tax paid from brokerage account
  rothConversionPreTaxFloor: 0,  // Preserve this much pre-tax balance (today's $); stop converting once pre-tax hits it (0 = no floor)
  // Conversion guardrail: pause or throttle conversions while the portfolio is
  // materially below where it stood when the programme began, measured in
  // today's dollars. A conversion is a discretionary, irreversible tax payment
  // funded by selling assets — making it in a down market sells shares cheap and
  // removes the ones that would have carried the recovery. Off by default: it
  // changes an existing plan's behaviour, so it is opt-in.
  rothConversionGuardrailEnabled: false,
  rothConversionGuardrailReturnFloor: 0, // pause when LAST year's portfolio return was below this
  rothConversionGuardrailFloor: 0,    // fraction of the normal conversion still done (0 = pause fully)
  // §72(t) SEPP: substantially equal periodic payments let you tap a pre-tax
  // account before 59½ without the 10% penalty, in exchange for locking the
  // payment schedule until 59½ or 5 years, whichever is longer. Off by default —
  // it's a deliberate strategy, not something to assume on a user's behalf.
  // (The 457(b) exemption and the rule of 55 are applied automatically from
  // account type and retirement age; they need no toggle.)
  sepp72tEnabled: false,
  heirTaxRate: 0.25,             // Heirs' assumed ordinary rate on inherited PRE-TAX dollars (SECURE Act 10-year drain) — used by the Roth optimizer's after-tax legacy score
  legacyAge: 95,                 // Planning horizon / legacy target age
  // Spending phases (go-go / slow-go / no-go): staged multipliers on base
  // retirement spending. Disabled by default — flat spending is the classic
  // (conservative) assumption; enabling this models the "retirement smile."
  spendingPhasesEnabled: false,
  goGoEndAge: 75,                // Last age of the go-go phase (inclusive)
  slowGoEndAge: 85,              // Last age of the slow-go phase (inclusive); no-go after
  goGoMultiplier: 1.0,           // Spending multiplier during go-go years
  slowGoMultiplier: 0.85,        // Spending multiplier during slow-go years
  noGoMultiplier: 0.75,          // Spending multiplier during no-go years
  // Survivor modeling: when enabled, models the financial impact of a spouse dying
  // before the planning horizon ends. Changes filing status, stops income streams,
  // and applies SS survivor benefit rules.
  survivorModelEnabled: false,
  survivorSpendingFactor: 0.75,  // Surviving spouse spends this fraction of the couple's target income
  myLifeExpectancy: 85,          // Expected age at death (primary)
  spouseLifeExpectancy: 87,      // Expected age at death (spouse)
  // Healthcare expense modeling
  healthcareModel: 'none',       // 'none','basic','moderate','comprehensive','custom' — default OFF: the engine's modeled costs overestimate for most people, so users should bake healthcare into their desired spending. Opt in on the Personal tab.
  pre65HealthcareAnnual: 12000,  // Annual healthcare cost per person before Medicare (ACA/employer)
  // Pre-65 coverage model: 'flat' = fixed annual cost above; 'aca' = retired
  // under-65 members buy marketplace coverage where the premium is MAGI-driven
  // (benchmark − premium tax credit, 2026 post-ARPA rules with the 400% FPL cliff).
  pre65Coverage: 'flat',
  acaBenchmarkPremium: 14000,    // Unsubsidized silver benchmark (SLCSP) per person/yr — replace with your healthcare.gov quote
  post65OOPAnnual: 2000,         // Annual out-of-pocket after Medicare (copays, dental, vision)
  includeMedigap: true,          // Include supplemental/Medigap insurance
  ltcModel: 'none',              // 'none','default','custom' — LTC off by default so the starter scenario doesn't show two large spike clusters at ages 82–84 (my LTC window) and 86–88 (spouse's). Real risk, but a probabilistic/insurance concern that confuses first-time users looking at point-estimate cash flow. Enable on the Personal tab when ready.
  ltcMonthlyAmount: 5900,        // Custom LTC monthly cost
  ltcDurationMonths: 28,         // How many months of LTC to plan for before death
  medicalInflation: 0.05         // Healthcare-specific inflation rate
};

// contributionGrowth is set to match inflationRate (3%) on the FIXED-DOLLAR rows so
// real contributions stay constant over the 30-year accumulation. 2% growth vs 3%
// inflation silently erodes real contributions ~1%/yr (~26% by year 30) and produces
// an unsustainable scenario.
//
// The percent-of-salary rows carry no growth rate: a share of a salary that already
// has its own COLA is inflation-tracking by construction, and stacking growth on top
// would compound twice.
// The two 401(k)s are percent-of-salary, which is the only entry mode that can
// hold the employee deferral and the employer match as separate, attributable
// numbers. They used to be a flat $20,000/$8,000 marked contributor:'both' — an
// amount nothing could split, so it counted toward neither side of the savings
// rate (which read 4.7%) and drew no pre-tax deduction at all.
//
// 8% / 3% are TYPICAL_DEFERRAL_RATE and TYPICAL_MATCH_RATE, the figures the
// Guided Setup wizard has always estimated from. The cold-start defaults and the
// wizard now agree; before this they held two different opinions about the same
// typical saver.
const DEFAULT_ACCOUNTS = [
  { id: 1, name: 'My 401(k)', type: '401k', balance: 60000, contributionMode: 'percent', employeePercent: TYPICAL_DEFERRAL_RATE, employerMatchPercent: TYPICAL_MATCH_RATE, cagr: 0.07, startAge: 35, stopAge: 65, owner: 'me', contributor: 'me' },
  { id: 2, name: 'Spouse 401(k)', type: '401k', balance: 30000, contributionMode: 'percent', employeePercent: TYPICAL_DEFERRAL_RATE, employerMatchPercent: TYPICAL_MATCH_RATE, cagr: 0.07, startAge: 33, stopAge: 65, owner: 'spouse', contributor: 'me' },
  { id: 3, name: 'My Roth IRA', type: 'roth_ira', balance: 15000, contribution: 6000, contributionGrowth: 0.03, cagr: 0.07, startAge: 35, stopAge: 65, owner: 'me', contributor: 'me' },
  { id: 4, name: 'Savings', type: 'brokerage', balance: 15000, contribution: 2400, contributionGrowth: 0.03, cagr: 0.04, startAge: 35, stopAge: 65, owner: 'joint', contributor: 'me' }
];

// Salary COLA and SS COLA set to 3% to match inflation. Lower values silently erode
// the real purchasing power of every income stream — SS benefits set at 2% COLA
// lose ~25% of their value by age 95 vs. real-world SS which tracks CPI.
//
// Salaries end at retirementAge − 1: age ranges here are INCLUSIVE, while an
// account's stopAge is exclusive, so `endAge: 65` against `stopAge: 65` had the
// couple earning a full salary at 65 while contributing nothing — a phantom
// year of pay after the age they retire. (The Guided Setup wizard already used
// retAge − 1; only these defaults disagreed.)
//
// Social Security is in TODAY'S dollars, which is how SSA quotes it on the
// statement people read these figures off — hence todaysDollars: true, so the
// benefit is indexed up to the claim year instead of being taken as the nominal
// 2058 amount. Without the flag this couple's benefit arrived worth $15,728 in
// today's money instead of $40,500: a 61% understatement that the portfolio then
// had to cover, and the single reason the starter plan used to sit one rounding
// error away from failing.
//
// The amounts are the 2026 PIA formula applied to each salary as a steady career
// average — 90% of the first $1,286 of AIME, 32% to $7,749, 15% above (SSA 2026
// bend points) — and `pia` is the same figure monthly, so the two fields cannot
// disagree. They did: 36000/yr sat next to a pia of 2400 ($28,800/yr), and the
// engine reads BOTH (pia drives the spousal benefit).
const DEFAULT_INCOME_STREAMS = [
  { id: 1, name: 'My Salary', type: 'earned_income', amount: 105000, startAge: 35, endAge: 64, cola: 0.03, owner: 'me' },
  { id: 2, name: 'Spouse Salary', type: 'earned_income', amount: 75000, startAge: 33, endAge: 64, cola: 0.03, owner: 'spouse' },
  { id: 3, name: 'My Social Security', type: 'social_security', amount: 40500, startAge: 67, endAge: 95, cola: 0.03, owner: 'me', pia: 3375, todaysDollars: true },
  { id: 4, name: 'Spouse Social Security', type: 'social_security', amount: 32940, startAge: 67, endAge: 95, cola: 0.03, owner: 'spouse', pia: 2745, todaysDollars: true }
];

// Home value tracks the national median existing-home price (NAR, Q1 2026:
// $404,300). It had drifted to $315,000 — roughly the 2019 median — which
// understated both the balance sheet and the property tax below.
const DEFAULT_ASSETS = [
  { id: 1, name: 'Primary Residence', type: 'real_estate', value: 405000, appreciationRate: 0.03, mortgage: 300000, mortgagePayoffAge: 60 },
  { id: 2, name: 'Vehicles', type: 'vehicle', value: 35000, appreciationRate: -0.10, mortgage: 0, mortgagePayoffAge: null }
];

// Recurring expenses: modeled separately from desiredRetirementIncome for granularity.
// Each expense has its own start/end age, inflation rate, and category.
// When recurringExpenses has entries, they ADD to the flat desiredRetirementIncome.
// The single placeholder below exists so the cash-flow tab isn't empty for first-time
// users — they can edit/delete it once they understand the feature.
const DEFAULT_RECURRING_EXPENSES = [
  { id: 1, name: 'Property Tax', category: 'housing', amount: 4400, startAge: 35, endAge: 95, inflationRate: 0.03, owner: 'me' }
];

// ── CURRENT-YEAR TAX DETAIL ──────────────────────────────────────────────────
// Everything the Form 1040 engine needs that the long-range plan does not carry:
// what has actually been earned, deferred and withheld so far, and the K-1s.
//
// PRIVACY: this lives in localStorage alongside the rest of the plan and travels
// in plan exports, which now carry wage and withholding detail. No field asks for
// an SSN or an EIN — `employerLabel` and `label` are free text for the user's own
// benefit and are never required.
const DEFAULT_CURRENT_YEAR = {
  taxYear: (typeof BASE_TAX_YEAR === 'number' ? BASE_TAX_YEAR : 2026),
  // One row per person per employer. `ytd` is copied straight off a paystub —
  // the stub's own YTD columns are the input, so nothing has to be derived.
  payroll: [],
  // One row per K-1, laid out by box number so it can be filled in from the form.
  k1s: [],
  estimatedPayments: { federal: [0, 0, 0, 0], state: [0, 0, 0, 0] },
  // Key lines off last year's return. Drives the §6654 safe harbor (which needs
  // prior AGI and prior total tax) and seeds items that are hard to project.
  priorYearReturn: { taxYear: null, agi: null, totalTax: null, totalWithheld: null,
                     deductionTaken: null, qbiDeduction: null },
  otherIncome: {},
  adjustments: {},
  deductions: { mode: 'auto' },
};

// A blank paystub row. asOfDate defaults to today so the period count is right
// the moment a row is added.
const newPayrollRow = (owner = 'me') => ({
  id: Date.now() + Math.random(),
  owner, employerLabel: '',
  asOfDate: new Date().toISOString().slice(0, 10),
  payFrequency: 'biweekly',
  ytd: { grossPay: 0, fedTaxableWages: 0, ssWages: 0, medicareWages: 0,
         preTax401kTraditional: 0, roth401k: 0, employerMatch: 0,
         hsa: 0, section125Health: 0, otherPreTax: 0,
         fedWithheld: 0, stateWithheld: 0, ssWithheld: 0, medicareWithheld: 0 },
  remainder: {},
});

// A blank K-1. Passive by default: that is both the common case for an interest
// held as an investment and the conservative one, since passive income carries
// 3.8% NIIT that a materially-participating owner would not owe.
const newK1Row = () => ({
  id: Date.now() + Math.random(),
  label: '', entityType: 'partnership',
  isPassive: true, materiallyParticipates: false,
  basisStart: 0, suspendedLossCarryforward: 0,
  boxes: { b1_ordinaryBusiness: 0, b2_rental: 0, b5_interest: 0,
           b6a_ordinaryDiv: 0, b6b_qualifiedDiv: 0,
           b8_shortTermGain: 0, b9a_longTermGain: 0, b13_deductions: 0,
           b14a_seEarnings: 0, b19_distributions: 0,
           b20z_qbi: 0, b20z_w2Wages: 0, b20z_ubia: 0, isSSTB: false },
});

// A savings rate is a magnitude with a judgement attached to it, so the bar
// carries the judgement and the number stays in text ink. They used to disagree:
// the figure was hardcoded amber (or emerald) while the bar ran a separate
// threshold ramp, so a 24.2% gross rate showed an amber number above a blue bar
// and a 31.2% net rate showed an emerald number above an amber one. Neither
// tile's colour said anything about the other.
// Recharts paints legend labels in the series colour. A label is text, and text
// wears text ink — a saturated hue at 11px on a dark ground is both a contrast
// problem and a second, redundant encoding of what the swatch beside it already
// says. This keeps the swatch coloured and the words readable.
const legendInk = (value) => <span style={{ color: THEME.inkSecondary }}>{value}</span>;

const savingsRateStatus = (rate) => rate >= 25 ? 'good' : rate >= 15 ? 'warning' : 'serious';

const formatCurrency = (value) => {
  if (value === undefined || value === null || isNaN(value)) return '$0';
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
};

// Is a Roth conversion planned at all, and in which mode? Three modes now —
// fixed amount, fill to a tax bracket, fill to an IRMAA tier — and six places
// used to test for the first two inline. A plan set to fill an IRMAA tier has
// neither a conversion amount nor a bracket label, so every one of those
// predicates would have read it as "no conversion planned" and hidden the
// column, skipped the validation, or described the strategy wrongly.
const conversionIsActive = (pi) => rothConversionIsPlanned(pi);
const conversionModeLabel = (pi) => rothConversionModeLabel(pi, formatCurrency);


const formatPercent = (value) => `${(value * 100).toFixed(1)}%`;

// Load data from localStorage. Returns null when there is nothing usable —
// missing key, parse error, OR a saved schemaVersion from a future build (B8).
// Missing schemaVersion is treated as v0 (pre-versioning) and accepted; future
// migrations can branch on saved.schemaVersion here.
function loadFromStorage() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (!saved) return null;
    const parsed = JSON.parse(saved);
    if (parsed && typeof parsed.schemaVersion === 'number' && parsed.schemaVersion > SCHEMA_VERSION) {
      console.warn(`Saved data is from a newer schema (v${parsed.schemaVersion}); this build only understands v${SCHEMA_VERSION}. Ignoring to avoid corruption.`);
      return null;
    }
    // Run forward migrations. Until v3 this gated on version but never actually
    // migrated, which was fine while every change was an optional field merged
    // from defaults. A new top-level key is not that, so the runner is real now.
    // Stops at the first missing step rather than skipping it, so a gap cannot
    // silently apply a later migration to data that never got an earlier one.
    let data = parsed;
    let version = (data && typeof data.schemaVersion === 'number') ? data.schemaVersion : 0;
    while (version < SCHEMA_VERSION) {
      const next = version + 1;
      const migrate = migrations[next];
      if (migrate) data = migrate(data);
      version = next;
    }
    return data;
  } catch (e) {
    console.error('Error loading from localStorage:', e);
  }
  return null;
};

// Save data to localStorage. Returns { ok: true } or { ok: false, reason } so
// the caller can surface quota / private-mode failures instead of silently
// losing the user's edits (B7).
function saveToStorage(data) {
  try {
    const payload = { ...data, schemaVersion: SCHEMA_VERSION };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
    return { ok: true };
  } catch (e) {
    console.error('Error saving to localStorage:', e);
    // QuotaExceededError is the common failure (large scenarios + big monte-carlo
    // history can push us past the ~5 MB origin cap). DOMException.name covers
    // both standard and Firefox's NS_ERROR_DOM_QUOTA_REACHED variant.
    const quota = e && (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED' || e.code === 22);
    return { ok: false, reason: quota ? 'quota' : 'unknown', error: e };
  }
};

// ============================================
// Spreadsheet-style Input Components
// These solve: select-on-focus, raw editing of formatted values,
// Enter/Tab to advance, Escape to revert
// ============================================

// Generic spreadsheet cell: selects all on focus, Enter advances to next input
// ============================================
// Spreadsheet Cell Components — select-on-focus, raw editing, same-column Enter nav
// ============================================
// Navigation helper: Enter moves to the same column in the next row (true spreadsheet behavior)
// Enter/Escape navigation for table cells
// Thin wrappers around plain <input>/<select> — matching the modal pattern.
// No onKeyDown, no editing state. Tab works natively.

// ============================================
// INPUT CELL COMPONENTS
// ============================================
// All number/percent/age cells follow a unified pattern that makes typing feel natural:
//
//   1. While focused: hold the user's typing as a raw string in local state. No
//      reformatting, no rounding, no division — what they type is what stays in
//      the field. This is critical because the previous implementation called
//      .toFixed(1) on every keystroke, which scrambled cursor position and
//      effectively prevented typing multi-digit numbers (e.g., typing "10"
//      registered as "1" because "1" → "1.0" → cursor jumped → next "0" replaced).
//
//   2. On change: store the raw string, parse-and-commit to parent only when
//      the string parses to a valid number. Empty string is allowed during typing.
//
//   3. On blur: format the final value cleanly and re-sync with parent (handles
//      cases like "1." or "" by treating them as 0).
//
//   4. On wheel: prevent the default behavior. Scroll-wheel on focused number
//      inputs is a common source of accidental value changes — we disable it.
//
//   5. Backward compatible: existing call sites use either `onChange(event)` or
//      `onValueChange(number)`. We support both — `onValueChange` is preferred
//      and takes a parsed number; `onChange` receives a synthetic event-like
//      object for compatibility with the older `e => Number(e.target.value)` pattern.

// Spreadsheet text cell — used for free-form text (no number coercion)
const SpreadsheetCell = ({ value, onChange, onCommit, className, ...props }) => (
  <input type="text" value={value} onChange={onChange} onBlur={onCommit} className={className} {...props} />
);

// Shared hook for number input behavior. Returns the props an <input> needs.
// `value` = the parent's committed numeric value
// `formatForDisplay(num)` = converts numeric value to string for display when NOT focused
// `parseFromInput(str)` = converts raw input string to numeric value to commit
// `commit(num)` = called with parsed number on change (when valid) and on blur
const useNumberInput = (value, formatForDisplay, parseFromInput, commit) => {
  const [focused, setFocused] = React.useState(false);
  const [raw, setRaw] = React.useState('');
  
  const displayValue = focused ? raw : formatForDisplay(value);
  
  return {
    value: displayValue,
    onFocus: (e) => {
      setFocused(true);
      // Pre-fill the editor with the current value (without formatting suffixes).
      // For percent: show "5" not "5.0". For age/currency: show "65" not "65.0".
      setRaw(formatForDisplay(value));
      // Select all text on focus so the user can immediately overwrite by typing.
      // This is the common spreadsheet behavior and what most users expect.
      e.target.select();
    },
    onChange: (e) => {
      const newRaw = e.target.value;
      setRaw(newRaw);
      // Commit only if it parses cleanly. Empty string / "1." / "-" stay local.
      const parsed = parseFromInput(newRaw);
      if (parsed !== null) commit(parsed);
    },
    onBlur: () => {
      setFocused(false);
      // Final commit: ensure parent has the cleaned-up value, even if the user
      // left something like "1." or "" in the field (treat as 0 or last valid).
      const parsed = parseFromInput(raw);
      if (parsed !== null) commit(parsed);
      else commit(value); // Re-commit existing value to trigger any onCommit logic
    },
    // Suppress scroll-wheel value changes — a common UX pitfall with type=number
    onWheel: (e) => e.target.blur(),
  };
};

// Currency input. Stores a plain number (dollars). Displays without commas
// in the input itself (browser-native number input doesn't support them).
const CurrencyCell = ({ value, onValueChange, onCommit, className, prefix = true, ...props }) => {
  const inputProps = useNumberInput(
    value,
    (num) => (num == null || num === 0 ? '' : String(num)),
    (str) => {
      if (str === '' || str === '-') return 0;
      const n = Number(str);
      return Number.isFinite(n) ? n : null;
    },
    (num) => onValueChange && onValueChange(num)
  );
  return (
    <div className="flex items-center justify-end">
      {prefix && <span className="text-slate-500 mr-1 text-sm">$</span>}
      <input type="number" inputMode="decimal" {...inputProps} {...props}
        onBlur={(e) => { inputProps.onBlur(e); if (onCommit) onCommit(); }}
        className={className} />
    </div>
  );
};

// Percent input. Parent stores fraction (0.05 = 5%). User types percent (5 = 5%).
// We convert: display value × 100, user input ÷ 100 on commit.
const PercentCell = ({ value, onValueChange, onCommit, className, ...props }) => {
  // Parent's value is a fraction (0.05); we work in percent display (5).
  // useNumberInput's value should be the "raw percent" not the fraction.
  // We translate at the boundary.
  const percentValue = (value || 0) * 100;
  const inputProps = useNumberInput(
    percentValue,
    (num) => {
      if (num == null || num === 0) return '';
      // Trim trailing zeros: 10.00 → "10", 10.50 → "10.5", 10.55 → "10.55"
      return Number(num.toFixed(4)).toString();
    },
    (str) => {
      if (str === '' || str === '-' || str === '.') return 0;
      const n = Number(str);
      return Number.isFinite(n) ? n : null;
    },
    (num) => onValueChange && onValueChange(num / 100)
  );
  return (
    <div className="flex items-center justify-end">
      <input type="number" inputMode="decimal" step="any" {...inputProps} {...props}
        onBlur={(e) => { inputProps.onBlur(e); if (onCommit) onCommit(); }}
        className={className} />
      <span className="text-slate-500 ml-0.5 text-sm">%</span>
    </div>
  );
};

// Age input. Plain integer-valued number input with the same UX treatment.
// Supports both `onChange(event)` (legacy) and `onValueChange(number)` (preferred).
const AgeCell = ({ value, onChange, onValueChange, onCommit, className, ...props }) => {
  const inputProps = useNumberInput(
    value,
    (num) => (num == null || num === 0 ? '' : String(num)),
    (str) => {
      if (str === '' || str === '-') return 0;
      const n = Number(str);
      return Number.isFinite(n) ? Math.round(n) : null;
    },
    (num) => {
      if (onValueChange) onValueChange(num);
      if (onChange) onChange({ target: { value: String(num) } }); // legacy event shape
    }
  );
  return (
    <input type="number" inputMode="numeric" {...inputProps} {...props}
      onBlur={(e) => { inputProps.onBlur(e); if (onCommit) onCommit(); }}
      className={className} />
  );
};


const GridSelect = ({ value, onChange, options, className, children, ...props }) => (
  <select value={value} onChange={onChange} className={className} {...props}>
    {children || options?.map(o => typeof o === 'string'
      ? <option key={o} value={o}>{o}</option>
      : <option key={o.value} value={o.value}>{o.label}</option>
    )}
  </select>
);

const InfoCard = React.memo(({ title, sections, isOpen, onToggle }) => {
  if (!isOpen) {
    return (
      <button
        tabIndex={-1}
        onClick={onToggle}
        className="flex items-center gap-1.5 text-amber-400/70 hover:text-amber-400 transition-colors px-2.5 py-1 rounded-full border border-amber-500/30 hover:border-amber-500/50 hover:bg-amber-500/10 text-xs font-medium"
        title={`What is ${title}?`}
      >
        <svg width="14" height="14" viewBox="0 0 20 20" fill="none">
          <circle cx="10" cy="10" r="9" stroke="currentColor" strokeWidth="1.5" />
          <text x="10" y="14.5" textAnchor="middle" fill="currentColor" fontSize="12" fontWeight="600">i</text>
        </svg>
        <span>Guide</span>
      </button>
    );
  }

  return (
    <div className="mt-3 mb-1 bg-slate-800/90 border border-amber-500/30 rounded-lg overflow-hidden">
      <div className="flex items-center justify-between px-4 py-2.5 bg-amber-500/10 border-b border-amber-500/20">
        <span className="text-sm font-semibold text-amber-400">ℹ️ Understanding: {title}</span>
        <button
          onClick={onToggle}
          className="text-slate-400 hover:text-slate-200 text-lg leading-none px-1"
        >
          ✕
        </button>
      </div>
      <div className="px-4 py-3 space-y-3 max-h-[28rem] overflow-y-auto">
        {sections.map((section, idx) => (
          <div key={idx}>
            {section.heading && (
              <div className="text-xs font-semibold text-amber-400/80 uppercase tracking-wide mb-1">{section.heading}</div>
            )}
            {section.body && (
              <p className="text-sm text-slate-300 leading-relaxed">{section.body}</p>
            )}
            {section.items && (
              <div className="space-y-1.5 mt-1">
                {section.items.map((item, i) => (
                  <div key={i} className="flex gap-2 text-sm">
                    <span className="flex-shrink-0 mt-0.5">{item.color && (
                      <span className="inline-block w-3 h-3 rounded-sm" style={{ backgroundColor: item.color }} />
                    )}{item.icon && <span>{item.icon}</span>}</span>
                    <div>
                      <span className="text-slate-200 font-medium">{item.label}</span>
                      {item.desc && <span className="text-slate-400"> — {item.desc}</span>}
                    </div>
                  </div>
                ))}
              </div>
            )}
            {section.tip && (
              <div className="mt-1.5 px-3 py-2 bg-amber-500/5 border-l-2 border-amber-500/40 rounded-r">
                <p className="text-xs text-amber-300/90">💡 {section.tip}</p>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
});
InfoCard.displayName = 'InfoCard';

// ============================================
// Shared Style Constants (Module Scope)
// Lifted out of RetirementPlanner so child components can be defined at module
// scope and avoid the unmount/remount cycle on every parent state change.
// ============================================
const cardStyle = "bg-gradient-to-br from-slate-800/80 to-slate-900/80 backdrop-blur-sm border border-slate-700/50 rounded-xl p-6 shadow-xl";

// ── SECTION SHELL ───────────────────────────────────────────────────────────
// One card, one heading, one hide control, driven by SECTION_MANIFEST. The
// dashboard's version of this was hand-written per section, which is why the
// section list existed twice; here a tab declares its sections once and wraps
// each one.
const Section = ({ tab, id, title, vis, level, setVis, actions, children, className }) => {
  if (!sectionIsVisible(vis, level, tab, id)) return null;
  const entry = (SECTION_MANIFEST[tab] || []).find(e => e.id === id);
  return (
    <div className={className || cardStyle}>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
        <div className="flex items-center gap-2">
          {typeof title === 'string'
            ? <h4 className="text-lg font-semibold text-slate-100">{title}</h4>
            : title}
          {actions}
        </div>
        {entry && (
          <button
            onClick={() => setVis(prev => ({ ...prev, [tab]: { ...(prev[tab] || {}), [id]: false } }))}
            className="text-xs text-slate-500 hover:text-slate-300 px-2 py-1 rounded hover:bg-slate-700/50 transition-colors shrink-0"
            title="Hide this section — restore it from Sections at the top of the tab"
          >
            Hide
          </button>
        )}
      </div>
      {children}
    </div>
  );
};

// The per-tab control strip: pick a detail level, or override any single section.
// The level is global so choosing Essentials once quiets every tab at once; the
// per-section chips are per tab and win over it.
const SectionControls = ({ tab, vis, setVis, level, setLevel }) => {
  const [open, setOpen] = useState(false);
  const entries = SECTION_MANIFEST[tab] || [];
  if (!entries.length) return null;
  const shown = entries.filter(e => sectionIsVisible(vis, level, tab, e.id)).length;
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2 text-sm">
          <span className="text-slate-500">Detail:</span>
          {SECTION_LEVELS.map(l => (
            <button
              key={l}
              onClick={() => setLevel(l)}
              className={`px-3 py-1 rounded-lg border text-xs capitalize transition-colors ${
                level === l
                  ? 'bg-amber-500/15 border-amber-500/40 text-amber-300'
                  : 'bg-slate-800/40 border-slate-700/40 text-slate-400 hover:text-slate-200'
              }`}
              title={l === 'essentials' ? 'Only what you need to judge whether the plan works'
                   : l === 'standard'  ? 'The ordinary working content of each tab'
                   : 'Everything, including diagnostics and methodology'}
            >
              {l}
            </button>
          ))}
        </div>
        <button
          onClick={() => setOpen(!open)}
          className="text-xs text-slate-400 hover:text-slate-200 px-3 py-1 rounded-lg border border-slate-700/40 hover:bg-slate-700/40 transition-colors"
        >
          {open ? 'Done' : `Sections (${shown}/${entries.length})`}
        </button>
      </div>
      {open && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
          {entries.map(e => {
            const on = sectionIsVisible(vis, level, tab, e.id);
            return (
              <button
                key={e.id}
                onClick={() => setVis(prev => ({ ...prev, [tab]: { ...(prev[tab] || {}), [e.id]: !on } }))}
                className={`px-3 py-2 rounded-lg border text-left text-xs transition-all ${
                  on ? 'bg-emerald-500/10 border-emerald-500/40 text-emerald-300'
                     : 'bg-slate-800/40 border-slate-700/40 text-slate-500'
                }`}
              >
                <div className="font-medium">{e.label}</div>
                <div className="mt-0.5 opacity-70">{on ? '✓ Visible' : '✗ Hidden'} · {e.level}</div>
              </button>
            );
          })}
          <button
            onClick={() => setVis(prev => ({ ...prev, [tab]: {} }))}
            className="px-3 py-2 rounded-lg border border-slate-700/40 text-xs text-slate-400 hover:text-slate-200 hover:bg-slate-700/40 transition-colors"
          >
            Reset to the “{level}” default
          </button>
        </div>
      )}
    </div>
  );
};
const inputStyle = "w-full bg-slate-900/80 border border-slate-600/50 rounded-lg px-4 py-2.5 text-slate-100 focus:outline-none focus:ring-2 focus:ring-amber-500/50 transition-all";
const labelStyle = "block text-sm font-medium text-slate-400 mb-1.5";
const buttonPrimary = "bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-400 hover:to-orange-400 text-slate-900 font-semibold px-6 py-2.5 rounded-lg transition-all shadow-lg";
const buttonSecondary = "bg-slate-700 hover:bg-slate-600 text-slate-100 font-medium px-4 py-2 rounded-lg transition-all";

// ============================================
// FAQTab — Lifted to module scope (no longer recreated on every parent render)
// ============================================
// ── AI ASSISTANT (bring-your-own-key) ────────────────────────────────────────
// The key lives in its own localStorage entry, NOT in the plan. handleExport
// writes the plan to the browser's download folder and the README tells people
// to serve this repo locally — a key inside that file would be one `git add .`
// from a public repository. Separate key, never exported, never in a scenario.
const AI_KEY_STORAGE = 'retirement_planner_ai_key';
const AI_MODEL = 'claude-opus-5';
const AI_API_URL = 'https://api.anthropic.com/v1/messages';

const loadAiKey = () => {
  try { return localStorage.getItem(AI_KEY_STORAGE) || ''; } catch { return ''; }
};
const saveAiKey = (key) => {
  try {
    if (key) localStorage.setItem(AI_KEY_STORAGE, key);
    else localStorage.removeItem(AI_KEY_STORAGE);
  } catch { /* private browsing — the key just won't persist */ }
};

// The one tool the model gets. It does not apply anything: it proposes, and the
// engine's validatePlanPatch decides whether the proposal is even expressible.
const AI_PATCH_TOOL = {
  name: 'propose_plan_changes',
  description:
    'Propose changes to the retirement plan. This does NOT apply anything — the changes are '
    + 'shown to the user as a before/after diff alongside the projected effect, and they choose '
    + 'whether to accept. Call this whenever the user asks for a change to their plan. Do not '
    + 'call it to answer a question that changes nothing.',
  input_schema: {
    type: 'object',
    properties: {
      summary: { type: 'string', description: 'One sentence describing the change as a whole.' },
      ops: {
        type: 'array',
        description: 'The individual edits, in the order they should be read.',
        items: {
          type: 'object',
          properties: {
            op: { type: 'string', enum: ['set', 'add', 'update', 'remove'] },
            target: { type: 'string', description: "'personalInfo' for set; otherwise the collection name." },
            field: { type: 'string', description: 'set only: the personalInfo field.' },
            value: { description: 'set only: the new value.' },
            id: { type: 'number', description: 'update/remove only: the id of the existing row.' },
            values: { type: 'object', description: 'add/update only: the fields to write.' },
            reason: { type: 'string', description: 'Why this specific edit, in one short sentence.' },
          },
          required: ['op', 'target'],
        },
      },
    },
    required: ['summary', 'ops'],
  },
};

// What the model is told about the plan. Deliberately the whole plan plus a
// projection summary: an assistant reasoning about a retirement plan from a
// partial view gives confidently wrong answers, and this is the data the user
// has already agreed to send.
const buildAiContext = (plan, projections) => {
  const last = projections && projections.length ? projections[projections.length - 1] : null;
  const firstBroke = (projections || []).find(r => (r.totalPortfolio || 0) <= 0);
  return {
    schema: planPatchSchema(plan),
    projection: {
      years: projections ? projections.length : 0,
      endingPortfolio: last ? Math.round(last.totalPortfolio || 0) : null,
      endingNetWorth: last ? Math.round(last.totalNetWorth || 0) : null,
      lifetimeTax: Math.round((projections || []).reduce((s, r) => s + (r.totalTax || 0), 0)),
      moneyRunsOutAtAge: firstBroke ? firstBroke.myAge : null,
    },
  };
};

const AI_SYSTEM_PROMPT = `You are a retirement-planning assistant embedded in a planning tool the user already owns. You have two jobs: answer questions about their plan, and propose changes to it.

You do not have the ability to change anything yourself. When the user asks for a change, call propose_plan_changes. The tool returns nothing — the app shows your proposal to the user as a before/after diff with the projected effect, and they accept or reject it. Say what you are proposing and why, briefly, alongside the call.

The <plan> block below is the user's complete plan, with every field you may change, its current value, and its units. Read it before proposing anything:

- Every rate is a DECIMAL FRACTION. 0.03 means 3%. The single exception is charitableGivingPercent, which is whole percent. Getting this wrong by a factor of 100 is the most damaging mistake available to you.
- You may only write fields listed in the schema. There is no way to add a new one, and a field you invent will be rejected.
- Ids are assigned by the app. Never choose one; use 'add' and the app assigns it.
- An account's stopAge is exclusive; an income stream's endAge is inclusive.

On judgment: this is the user's money and their decision. Make the routine calls yourself rather than asking — if they say "bump my savings rate to 12%", change it, don't ask which account. Ask only when two readings of the request would produce materially different plans. If you think the request is a mistake, say so in a sentence and propose it anyway; they can decline.

Do not give tax or investment advice as though you were their advisor, and do not claim certainty the projection does not have. The numbers in the plan came from the user; the projected consequences come from the app's engine, not from you — never state a projected outcome you have not been given.`;

function AiAssistantTab({ plan, projections, onApply }) {
  const [apiKey, setApiKey] = useState(loadAiKey);
  const [keyDraft, setKeyDraft] = useState('');
  const [messages, setMessages] = useState([]);      // API-shaped conversation
  const [input, setInput] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [proposal, setProposal] = useState(null);    // { toolUseId, summary, ops, diff, preview }
  const [usage, setUsage] = useState(null);
  const [showPayload, setShowPayload] = useState(false);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, busy, proposal]);

  const context = useMemo(() => buildAiContext(plan, projections), [plan, projections]);

  // Price the proposal with the engine, not with the model. This is the whole
  // point of the review step: the reader sees what the change does to THEIR
  // plan, computed the same way every other number in the app is computed.
  const priceProposal = (ops) => {
    const diff = describePlanPatch(plan, ops);
    const { state: next, ok } = applyPlanPatch(plan, ops);
    let preview = null;
    try {
      const after = computeProjections(next.personalInfo, next.accounts, next.incomeStreams,
        next.assets, next.oneTimeEvents, next.recurringExpenses, new Date().getFullYear());
      const lastA = after[after.length - 1];
      const lastB = projections && projections.length ? projections[projections.length - 1] : null;
      const brokeA = after.find(r => (r.totalPortfolio || 0) <= 0);
      const brokeB = (projections || []).find(r => (r.totalPortfolio || 0) <= 0);
      preview = {
        endingBefore: lastB ? lastB.totalPortfolio || 0 : 0,
        endingAfter: lastA ? lastA.totalPortfolio || 0 : 0,
        taxBefore: (projections || []).reduce((s, r) => s + (r.totalTax || 0), 0),
        taxAfter: after.reduce((s, r) => s + (r.totalTax || 0), 0),
        breaksBefore: brokeB ? brokeB.myAge : null,
        breaksAfter: brokeA ? brokeA.myAge : null,
      };
    } catch (e) {
      preview = { failed: e.message };
    }
    return { diff, next, ok, preview };
  };

  // One request. Returns the assistant message so the caller can decide what to
  // do with a tool call. Errors are surfaced verbatim — a 401 from a mistyped
  // key and a 429 from a spent quota need different fixes, and paraphrasing
  // them into "something went wrong" hides which one it is.
  const callClaude = async (history) => {
    const res = await fetch(AI_API_URL, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        // Required for browser-origin calls. Named "dangerous" because it means
        // the key is in the page — which is exactly the bring-your-own-key
        // bargain this feature makes, and why the key is never sent anywhere
        // but api.anthropic.com.
        'anthropic-dangerous-direct-browser-access': 'true',
      },
      body: JSON.stringify({
        model: AI_MODEL,
        max_tokens: 16000,
        output_config: { effort: 'medium' },
        system: `${AI_SYSTEM_PROMPT}\n\n<plan>\n${JSON.stringify(context, null, 1)}\n</plan>`,
        tools: [AI_PATCH_TOOL],
        messages: history,
      }),
    });
    const body = await res.json().catch(() => null);
    if (!res.ok) {
      const detail = body && body.error ? `${body.error.type}: ${body.error.message}` : `HTTP ${res.status}`;
      throw new Error(detail);
    }
    return body;
  };

  const send = async (text) => {
    if (!text.trim() || busy) return;
    setError(null);

    // An unresolved tool_use has to be answered before the next user turn — the
    // API rejects the request otherwise. Typing instead of deciding is a
    // decline, and the model is told so rather than left to guess.
    const history = messages.slice();
    if (proposal) {
      history.push({
        role: 'user',
        content: [{ type: 'tool_result', tool_use_id: proposal.toolUseId,
                    content: 'The user did not apply these changes; they replied instead.' }],
      });
      setProposal(null);
    }
    history.push({ role: 'user', content: text });
    setMessages(history);
    setInput('');
    setBusy(true);
    try {
      const reply = await callClaude(history);
      setUsage(reply.usage || null);
      const next = history.concat([{ role: 'assistant', content: reply.content }]);
      setMessages(next);
      const toolUse = (reply.content || []).find(b => b.type === 'tool_use');
      if (toolUse && Array.isArray(toolUse.input && toolUse.input.ops)) {
        const priced = priceProposal(toolUse.input.ops);
        setProposal({ toolUseId: toolUse.id, summary: toolUse.input.summary, ops: toolUse.input.ops, ...priced });
      }
      if (reply.stop_reason === 'refusal') {
        setError('Claude declined to answer that. Try rephrasing.');
      }
    } catch (e) {
      setError(e.message);
      setMessages(messages);   // roll back the optimistic user turn
    } finally {
      setBusy(false);
    }
  };

  const resolveProposal = (accepted) => {
    if (!proposal) return;
    if (accepted) onApply(proposal.next);
    setMessages(prev => prev.concat([{
      role: 'user',
      content: [{ type: 'tool_result', tool_use_id: proposal.toolUseId,
                  content: accepted ? 'The user applied these changes.' : 'The user declined these changes.' }],
    }]));
    setProposal(null);
  };

  // ── Key setup ────────────────────────────────────────────────────────────
  if (!apiKey) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-100">AI Assistant</h2>
          <p className="text-slate-400 mt-1">Ask about your plan, or describe a change and review it before it lands.</p>
        </div>
        <div className={cardStyle}>
          <h3 className="text-lg font-semibold text-slate-100 mb-3">Connect your Anthropic API key</h3>
          <p className="text-sm text-slate-400 mb-4">
            This app is a static site with no server, so there is nowhere for it to keep an API key on your
            behalf — you bring your own. It is stored in this browser only, under its own key, and is
            <strong className="text-slate-200"> never included in a plan export or a scenario</strong>. Requests go
            straight from this page to <code className="text-amber-400">api.anthropic.com</code> and nowhere else.
          </p>
          <div className="bg-amber-900/20 border border-amber-500/30 rounded-lg p-4 mb-4 text-sm text-amber-200/90">
            <strong>What leaves your browser.</strong> Turning this on is the first time this tool sends anything
            anywhere. Each message sends your plan — ages, balances, contribution rates, income, and the
            projection summary — to Anthropic's API so the assistant can reason about it. It does not send your
            name, your account numbers, or anything from the Current Year tab. Nothing is sent until you type a
            message, and you can disconnect at any time.
          </div>
          <label className={labelStyle}>API key</label>
          <input
            type="password" value={keyDraft} onChange={e => setKeyDraft(e.target.value)}
            placeholder="sk-ant-..." className={inputStyle} autoComplete="off" spellCheck={false}
          />
          <div className="flex items-center gap-3 mt-4">
            <button
              className={buttonPrimary}
              disabled={!keyDraft.trim()}
              onClick={() => { saveAiKey(keyDraft.trim()); setApiKey(keyDraft.trim()); setKeyDraft(''); }}
            >
              Connect
            </button>
            <a href="https://console.anthropic.com/settings/keys" target="_blank" rel="noreferrer"
               className="text-sm text-amber-400 hover:text-amber-300">Get a key →</a>
          </div>
          <p className="text-xs text-slate-500 mt-4">
            Usage is billed to your own Anthropic account. A typical question costs a fraction of a cent;
            the plan is re-sent with every message, so a long conversation costs more than a short one.
          </p>
        </div>
      </div>
    );
  }

  // ── Conversation ─────────────────────────────────────────────────────────
  const shown = messages.filter(m =>
    typeof m.content === 'string' || (Array.isArray(m.content) && m.content.some(b => b.type === 'text')));

  return (
    <div className="space-y-6">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-100">AI Assistant</h2>
          <p className="text-slate-400 mt-1">Every proposed change is shown as a diff, priced by the engine, and applied only when you say so.</p>
        </div>
        <button
          className="text-xs text-slate-400 hover:text-slate-200 border border-slate-600 rounded-lg px-3 py-1.5"
          onClick={() => { saveAiKey(''); setApiKey(''); setMessages([]); setProposal(null); setUsage(null); }}
        >
          Disconnect key
        </button>
      </div>

      <div className={cardStyle}>
        <div ref={scrollRef} className="max-h-[420px] overflow-y-auto space-y-4 pr-1">
          {shown.length === 0 && (
            <div className="text-sm text-slate-500 space-y-2">
              <p>Try:</p>
              <ul className="list-disc list-inside space-y-1">
                <li>“Why does my plan run out of money at 88?”</li>
                <li>“Raise my 401(k) deferral to 12% and show me what it does.”</li>
                <li>“Add a $40,000 one-time expense at 62 for a new roof.”</li>
                <li>“What happens if I retire two years earlier?”</li>
              </ul>
            </div>
          )}
          {shown.map((m, i) => {
            const text = typeof m.content === 'string'
              ? m.content
              : m.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
            const mine = m.role === 'user';
            return (
              <div key={i} className={mine ? 'text-right' : ''}>
                <div className={`inline-block text-left max-w-[85%] rounded-xl px-4 py-2.5 text-sm whitespace-pre-wrap ${
                  mine ? 'bg-amber-600/20 border border-amber-500/30 text-amber-100'
                       : 'bg-slate-900/60 border border-slate-700/50 text-slate-200'}`}>
                  {text}
                </div>
              </div>
            );
          })}
          {busy && <div className="text-sm text-slate-500">Thinking…</div>}
        </div>

        {error && (
          <div className="mt-4 bg-red-900/20 border border-red-500/30 rounded-lg p-3 text-sm text-red-300">
            {error}
          </div>
        )}

        <div className="mt-4 flex gap-2">
          <input
            type="text" value={input} onChange={e => setInput(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(input); } }}
            placeholder="Ask about your plan, or describe a change…"
            className={inputStyle} disabled={busy}
          />
          <button className={buttonPrimary} disabled={busy || !input.trim()} onClick={() => send(input)}>Send</button>
        </div>

        <div className="mt-3 flex items-center justify-between text-xs text-slate-500">
          <button className="hover:text-slate-300 underline decoration-dotted"
                  onClick={() => setShowPayload(v => !v)}>
            {showPayload ? 'Hide' : 'Show'} exactly what gets sent
          </button>
          {usage && (
            <span>
              last turn: {usage.input_tokens?.toLocaleString()} in / {usage.output_tokens?.toLocaleString()} out
            </span>
          )}
        </div>
        {showPayload && (
          <pre className="mt-3 max-h-64 overflow-auto text-[11px] text-slate-400 bg-slate-950/60 border border-slate-700/50 rounded-lg p-3">
{JSON.stringify(context, null, 1)}
          </pre>
        )}
      </div>

      {proposal && (
        <div className="bg-gradient-to-br from-emerald-900/20 to-slate-900/80 border border-emerald-500/30 rounded-xl p-6 shadow-xl">
          <h3 className="text-lg font-semibold text-slate-100">Proposed change</h3>
          <p className="text-sm text-slate-300 mt-1">{proposal.summary}</p>

          <div className="mt-4 space-y-2">
            {proposal.diff.map((d, i) => (
              <div key={i} className={`rounded-lg border px-3 py-2 text-sm ${
                d.valid ? 'bg-slate-900/60 border-slate-700/50' : 'bg-red-900/20 border-red-500/30'}`}>
                <div className={d.valid ? 'text-slate-200' : 'text-red-300'}>{d.summary}</div>
                {d.reason && <div className="text-xs text-slate-500 mt-0.5">{d.reason}</div>}
                {d.warnings && d.warnings.map((w, j) => (
                  <div key={j} className="text-xs text-amber-400 mt-1">⚠ {w}</div>
                ))}
              </div>
            ))}
          </div>

          {/* The consequence, from the engine. The model's account of what its
              own change does is not evidence; this is. */}
          {proposal.preview && !proposal.preview.failed && (
            <div className="mt-4 grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div className="bg-slate-900/60 border border-slate-700/50 rounded-lg p-3">
                <div className="text-xs text-slate-500">Ending portfolio</div>
                <div className="text-sm text-slate-300">{formatCurrency(proposal.preview.endingBefore)} → <span className={
                  proposal.preview.endingAfter >= proposal.preview.endingBefore ? 'text-emerald-400' : 'text-red-400'
                }>{formatCurrency(proposal.preview.endingAfter)}</span></div>
              </div>
              <div className="bg-slate-900/60 border border-slate-700/50 rounded-lg p-3">
                <div className="text-xs text-slate-500">Lifetime tax</div>
                <div className="text-sm text-slate-300">{formatCurrency(proposal.preview.taxBefore)} → <span className={
                  proposal.preview.taxAfter <= proposal.preview.taxBefore ? 'text-emerald-400' : 'text-red-400'
                }>{formatCurrency(proposal.preview.taxAfter)}</span></div>
              </div>
              <div className="bg-slate-900/60 border border-slate-700/50 rounded-lg p-3">
                <div className="text-xs text-slate-500">Money runs out</div>
                <div className="text-sm text-slate-300">
                  {proposal.preview.breaksBefore ? `age ${proposal.preview.breaksBefore}` : 'never'}
                  {' → '}
                  <span className={proposal.preview.breaksAfter ? 'text-red-400' : 'text-emerald-400'}>
                    {proposal.preview.breaksAfter ? `age ${proposal.preview.breaksAfter}` : 'never'}
                  </span>
                </div>
              </div>
            </div>
          )}
          {proposal.preview && proposal.preview.failed && (
            <div className="mt-4 text-sm text-red-300">
              The proposed plan could not be projected ({proposal.preview.failed}) — don't apply it.
            </div>
          )}

          <div className="flex items-center gap-3 mt-5">
            <button
              className={buttonPrimary}
              disabled={!proposal.diff.some(d => d.valid) || (proposal.preview && proposal.preview.failed)}
              onClick={() => resolveProposal(true)}
            >
              Apply {proposal.diff.filter(d => d.valid).length} change{proposal.diff.filter(d => d.valid).length === 1 ? '' : 's'}
            </button>
            <button className={buttonSecondary} onClick={() => resolveProposal(false)}>Discard</button>
            {!proposal.ok && (
              <span className="text-xs text-amber-400">
                Some operations were rejected and will be skipped.
              </span>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

